#!/bin/bash
# RTC — génération des tomes de fondation T1 à T4 : plan (Dialagram, sous contraintes), rédaction, nettoyage, PDF.
# Claude écrit seulement les consignes ci-dessous, puis relit chaque tome avant publication.
O=/home/user/agentsecctest1/bibliotheque/outils
D=/home/user/agentsecctest1/NCE/09_PUBLICATIONS
REGLES="RÈGLES ABSOLUES : (1) ne citer QUE les références de la liste ci-dessous, avec l'auteur et l'année indiqués ; n'en inventer aucune ; aucun DOI, aucun numéro de page, aucune citation entre guillemets attribuée à un chercheur ; (2) ne jamais présenter une intuition comme une preuve ; donner des preuves complètes pour les résultats démontrés dans le livre, et pour les grands théorèmes connus donner l'idée de la preuve en le disant ; (3) chaque affirmation porte un statut : PROUVÉ, CONNU, EXPÉRIMENTAL, CONJECTURE, RÉFUTÉ ou OUVERT ; (4) aucune annonce de découverte ; (5) formules en LaTeX entre \$...\$ ou \$\$...\$\$ ; (6) lecteur cultivé non spécialiste : intuition, définition, énoncé, exemple, exercice ; (7) dernier chapitre : « Transfert vers le programme RTC » (ce que ce tome apporte à l'étude des traductions à ressources : quelles ressources, quelles traductions, quelles questions ouvertes)."

livre() {  # $1 dossier, $2 titre, $3 sujet, $4 références
  mkdir -p $D/$1 && cd $D/$1
  cat > brief_plan.txt <<EOF
Tu es l'auteur, pour le compte d'Oussama Ghorbel, d'un livre de la collection scientifique « Les Traductions du Calcul » (programme de recherche RTC : étudier quelles ressources — taille, temps, mémoire, profondeur, largeur, précision, partage — chaque traduction entre modèles de calcul conserve ou perd). Titre : « $2 ». Sujet : $3

$REGLES

Références autorisées (et seulement elles) : $4

Conçois le plan d'un livre d'environ 220 pages : 4 parties, 16 chapitres (le 16e est le transfert vers RTC), 4 à 6 sections par chapitre, exercices. Réponds UNIQUEMENT avec un JSON valide, sans balises markdown :
{"titre":"$2","sous_titre":"...","these":"...","cadre":{"nom":"Les traductions à ressources et le registre des statuts","description":"(recopie ici intégralement les règles absolues ci-dessus et la liste des références autorisées)"},"bibliographie":[{"auteur":"...","titre":"...","annee":"...","idee":"...","apport":"..."}],"parties":[{"titre":"...","chapitres":[{"numero":1,"titre":"...","objectif":"...","sections":["..."],"exercices":["..."]}]}]}
EOF
  for i in 1 2 3; do
    [ -s plan.json ] && break
    python3 $O/ask.py brief_plan.txt plan_raw.txt
    python3 -c "
import json;t=open('plan_raw.txt').read().strip()
if t.startswith('\`\`\`'): t=t.split('\n',1)[1].rsplit('\`\`\`',1)[0]
p=json.loads(t);assert sum(len(x['chapitres']) for x in p['parties'])>=14
json.dump(p,open('plan.json','w'),ensure_ascii=False,indent=1)" 2>/dev/null || rm -f plan.json
  done
  [ -s plan.json ] || { echo "$1 ERREUR plan"; return; }
  python3 -u $O/redaction.py plan.json chapitres --parallele 4 > redaction.log 2>&1
  python3 -u $O/nettoyage.py chapitres chapitres_v2 > nettoyage.log 2>&1
  python3 $O/mise_en_page.py plan.json chapitres_v2 livre.pdf --corps 11.3 > pdf.log 2>&1
  echo "$1 FIN $(ls chapitres_v2/*.md 2>/dev/null | wc -l) fichiers ; $(tail -1 pdf.log)"
}

livre T1 "Le Lambda-calcul" "le lambda-calcul comme structure fonctionnelle du calcul : termes, alpha-équivalence, bêta-réduction, substitution, stratégies d'évaluation, confluence (Church-Rosser), normalisation et divergence, encodages de Church, combinateurs et récursion (combinateur Y), lambda-calcul simplement typé et normalisation forte, correspondance de Curry-Howard, machines abstraites (SECD, Krivine), coût de la réduction (modèle de coût invariant), partage et réduction optimale." "Church 1936 (An unsolvable problem of elementary number theory) ; Turing 1937 (Computability and lambda-definability) ; Church et Rosser 1936 (Some properties of conversion) ; Landin 1964 (The mechanical evaluation of expressions) ; Barendregt 1984 (The Lambda Calculus: Its Syntax and Semantics) ; Howard 1980 (The formulae-as-types notion of construction) ; Lamping 1990 (An algorithm for optimal lambda calculus reduction) ; Pierce 2002 (Types and Programming Languages) ; Krivine 2007 (A call-by-name lambda-calculus machine) ; Hindley et Seldin 2008 (Lambda-Calculus and Combinators: An Introduction) ; Accattoli et Dal Lago 2016 ((Leftmost-outermost) beta reduction is invariant, indeed)" &
livre T2 "Les Machines de Turing" "les machines de Turing comme modèle de l'exécution : états, ruban, transitions, configurations, machines déterministes et non déterministes, multi-rubans et leur simulation, machine universelle, indécidabilité de l'arrêt, classes de temps et d'espace (P, NP, PSPACE), théorèmes de hiérarchie, simulation par circuits (taille O(t log t)), machines d'espace borné et automates finis, coût des simulations." "Turing 1936 (On computable numbers, with an application to the Entscheidungsproblem) ; Kleene 1956 (Representation of events in nerve nets and finite automata) ; Hartmanis et Stearns 1965 (On the computational complexity of algorithms) ; Hennie et Stearns 1966 (Two-tape simulation of multitape Turing machines) ; Savitch 1970 (Relationships between nondeterministic and deterministic tape complexities) ; Cook 1971 (The complexity of theorem-proving procedures) ; Pippenger et Fischer 1979 (Relations among complexity measures) ; Hopcroft et Ullman 1979 (Introduction to Automata Theory, Languages, and Computation) ; Papadimitriou 1994 (Computational Complexity) ; Sipser 1997 (Introduction to the Theory of Computation) ; Arora et Barak 2009 (Computational Complexity: A Modern Approach)" &
livre T3 "Circuits, Contraintes et SAT" "les circuits booléens comme objet pivot et SAT comme problème : logique propositionnelle, formes CNF et DNF, circuits et leur taille et profondeur, encodage de Tseitin, théorème de Cook-Levin et tableaux de calcul, 3-SAT, résolution et complexité des preuves, algorithmes DPLL et CDCL, propagation unitaire, apprentissage de clauses, SAT et largeur arborescente, transition de phase du 3-SAT aléatoire, encodage de problèmes réels (planification, vérification bornée). Résultat du programme à inclure avec statut PROUVÉ : lemme L-01, pour un circuit de degré d'entrée au plus k et de largeur arborescente w, la CNF de Tseitin a un graphe primal de largeur au plus (k+1)(w+1)-1 (preuve : remplacer chaque sac B par la réunion de ses sommets et de leurs entrées ; couverture, connexité, taille)." "Tseitin 1968 (On the complexity of derivation in propositional calculus) ; Cook 1971 (The complexity of theorem-proving procedures) ; Levin 1973 (Universal sequential search problems) ; Davis et Putnam 1960 (A computing procedure for quantification theory) ; Davis, Logemann et Loveland 1962 (A machine program for theorem-proving) ; Kautz et Selman 1992 (Planning as satisfiability) ; Marques-Silva et Sakallah 1999 (GRASP: a search algorithm for propositional satisfiability) ; Biere, Cimatti, Clarke et Zhu 1999 (Symbolic model checking without BDDs) ; Schöning 1999 (A probabilistic algorithm for k-SAT and constraint satisfaction problems) ; Impagliazzo et Paturi 2001 (On the complexity of k-SAT) ; Biere, Heule, van Maaren et Walsh 2009 (Handbook of Satisfiability) ; Pipatsrisawat et Darwiche 2011 (On the power of clause-learning SAT solvers as resolution engines) ; Jukna 2012 (Boolean Function Complexity: Advances and Frontiers)" &
livre T4 "Les Réseaux de Neurones comme Machines" "les réseaux de neurones comme modèle de calcul et leurs ressources : neurone à seuil et portes logiques, perceptron et ses limites (parité, XOR), circuits à seuil et taille des poids, réseaux multicouches, fonctions d'activation (sigmoïde, ReLU), approximation universelle, bénéfices de la profondeur, rétropropagation, réseaux récurrents et Turing-complétude, rôle de la précision des poids (rationnels, réels), transformers et leurs limites à précision bornée, représentation exacte contre approximation. Résultats du programme à inclure avec statut PROUVÉ : lemme L-03 (compilation porte par porte d'un circuit en neurones à seuil, poids entiers de valeur absolue au plus 2 : ET = [a+b>=2], OU = [a+b>=1], OU exclusif = [a+b-2h>=1] avec h = ET(a,b)) ; et avec statut EXPÉRIMENTAL : réseaux 16-16 entraînés puis élagués sur parité 8 bits, majorité 8 bits et addition 3+3 bits ont une largeur d'au moins 11 à 14 contre 1 à 3 pour les réseaux compilés (élagage grossier, limite à signaler)." "McCulloch et Pitts 1943 (A logical calculus of the ideas immanent in nervous activity) ; Rosenblatt 1958 (The perceptron) ; Minsky et Papert 1969 (Perceptrons) ; Hopfield 1982 (Neural networks and physical systems with emergent collective computational abilities) ; Rumelhart, Hinton et Williams 1986 (Learning representations by back-propagating errors) ; Cybenko 1989 (Approximation by superpositions of a sigmoidal function) ; Hornik, Stinchcombe et White 1989 (Multilayer feedforward networks are universal approximators) ; Hajnal, Maass, Pudlák, Szegedy et Turán 1993 (Threshold circuits of bounded depth) ; Håstad 1994 (On the size of weights for threshold gates) ; Siegelmann et Sontag 1995 (On the computational power of neural nets) ; Goodfellow, Bengio et Courville 2016 (Deep Learning) ; Telgarsky 2016 (Benefits of depth in neural networks) ; Vaswani et al. 2017 (Attention is all you need) ; Pérez, Marinković et Barceló 2019 (On the Turing completeness of modern neural network architectures) ; Merrill et Sabharwal 2023 (The parallelism tradeoff: limitations of log-precision transformers)" &
wait
